class Solution:
    def stringIndices(self, wordsContainer: List[str], wordsQuery: List[str]) -> List[int]:
        # Build the trie
        root = TrieNode()

        for idx, word in enumerate(wordsContainer):
            reversed_word = word[::-1]
            current = root
            # Update the current node with the current word's info
            if current.min_length > len(word):
                current.min_length = len(word)
                current.best_index = idx
            else:
                if current.min_length == len(word) and current.best_index > idx:
                    current.best_index = idx
            # Insert the rest of the reversed word into the trie
            for ch in reversed_word:
                if ch not in current.children:
                    current.children[ch] = TrieNode()
                current = current.children[ch]
                # Update the current node with the current word's info
                if current.min_length > len(word):
                    current.min_length = len(word)
                    current.best_index = idx
                else:
                    if current.min_length == len(word) and current.best_index > idx:
                        current.best_index = idx

        # Process each query
        result = []
        for query in wordsQuery:
            reversed_query = query[::-1]
            current = root
            for ch in reversed_query:
                if ch in current.children:
                    current = current.children[ch]
                else:
                    break
            result.append(current.best_index)

        return result
