class TrieNode:
    def __init__(self):
        self.children = {}
        self.best_len = float('inf')
        self.best_index = -1

class Solution:
    def stringIndices(self, wordsContainer: List[str], wordsQuery: List[str]) -> List[int]:
        # Initialize root of the trie
        root = TrieNode()

        # Preprocess the wordsContainer to insert into the trie
        for idx, word in enumerate(wordsContainer):
            reversed_word = word[::-1]
            current_node = root
            # Update the best info for the current node (root)
            if current_node.best_len > len(word) or (current_node.best_len == len(word) and current_node.best_index > idx):
                current_node.best_len = len(word)
                current_node.best_index = idx
            # Insert the reversed word into the trie
            for char in reversed_word:
                if char not in current_node.children:
                    current_node.children[char] = TrieNode()
                current_node = current_node.children[char]
                # Update the best info for the current node (which represents longer prefix)
                if current_node.best_len > len(word) or (current_node.best_len == len(word) and current_node.best_index > idx):
                    current_node.best_len = len(word)
                    current_node.best_index = idx

        # Process each query
        result = []
        for query in wordsQuery:
            reversed_query = query[::-1]
            current_node = root
            # Traverse the trie as far as possible
            for char in reversed_query:
                if char in current_node.children:
                    current_node = current_node.children[char]
                else:
                    break
            # The current_node holds the best index for the longest suffix
            result.append(current_node.best_index)

        return result

