class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        sets = [set(prop) for prop in properties]
        adj = [[] for _ in range(n)]

        for i in range(n):
            for j in range(n):
                if i != j:
                    common = len(sets[i] & sets[j])
                    if common >= k:
                        adj[i].append(j)

        visited = [False] * n
        count = 0

        for i in range(n):
            if not visited[i]:
                count += 1
                queue = deque([i])
                visited[i] = True
                while queue:
                    node = queue.popleft()
                    for neighbor in adj[node]:
                        if not visited[neighbor]:
