class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        if n == 0:
            return 0

        # Precompute the sets for each property list
        sets = [set(arr) for arr in properties]

        parent = list(range(n))
        rank = [1] * n
        count = n  # Number of connected components

        def find(x: int) -> int:
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x: int, y: int) -> bool:
            x_root = find(x)
            y_root = find(y)
            if x_root == y_root:
                return False
            # Union by rank
            if rank[x_root] < rank[y_root]:
                parent[x_root] = y_root
            else:
                parent[y_root] = x_root
                if rank[x_root] == rank[y_root]:
                    rank[x_root] += 1
            return True

        for i in range(n):
            for j in range(i + 1, n):
                # Calculate the intersection size
                intersect_size = len(sets[i] & sets[j])
                if intersect_size >= k:
                    if find(i) != find(j):
                        union(i, j)
                        count -= 1

        return count
